PREFIX hyobs:  <https://w3id.org/hmontology/>
 PREFIX sosa:   <http://www.w3.org/ns/sosa/>
 PREFIX schema: <http://schema.org/>
 PREFIX qudt:   <http://qudt.org/schema/qudt/>
 PREFIX xsd:    <http://www.w3.org/2001/XMLSchema#>
 PREFIX chebi:  <http://purl.obolibrary.org/obo/CHEBI_>

 SELECT ?month ?medianNO3N
 WHERE {
   GRAPH <hydroturtle/quadica> {
     {
       SELECT ?month (MAX(xsd:decimal(?val)) AS ?medianNO3N)
       WHERE {
         ?sensor a sosa:Sensor ;
                 schema:name ?stationName.

       FILTER(str(?stationName) = "BW_CEL904")

         ?obs a sosa:Observation ;
             sosa:madeBySensor ?sensor ;
             sosa:observedProperty hyobs:NO3NConcentrationMedian ;
             hyobs:hasAnalyte chebi:17632 ;
             sosa:resultTime ?t ;
             sosa:hasResult ?res .

         ?res qudt:numericValue ?val .

         FILTER(YEAR(?t) = 2005)

         BIND(MONTH(?t) AS ?month)
       }
       GROUP BY ?month
       ORDER BY DESC(?medianNO3N)
       LIMIT 1
     }
   }
 }

generated_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?year
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?obs a sosa:Observation ;
         hyobs:fractionAreaInGermany ?fraction ;
         hyobs:qMedian ?median ;
         sosa:resultTime ?date .
    FILTER(?fraction = 1)
    BIND(YEAR(xsd:dateTime(?date)) AS ?year)
    {
      SELECT (AVG(?m) AS ?longTermMedian)
      WHERE {
        GRAPH <hydroturtle/quadica> {
          ?o a sosa:Observation ;
             hyobs:fractionAreaInGermany ?f ;
             hyobs:qMedian ?m .
          FILTER(?f = 1)
        }
      }
    }
    FILTER(?median < ?longTermMedian)
  }
}

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa:  <http://www.w3.org/ns/sosa/>
PREFIX qudt:  <http://qudt.org/schema/qudt/>
PREFIX xsd:   <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?nationalMedianQ ?longTermMedianQ
WHERE {
  GRAPH <hydroturtle/quadica> 
  {
    {
      SELECT ?year (AVG(xsd:decimal(?val)) AS ?nationalMedianQ)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty hyobs:DischargeMedian ;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .
        ?res qudt:numericValue ?val .
        BIND(YEAR(?t) AS ?year)
      }
      GROUP BY ?year
    }
    {
      SELECT (AVG(xsd:decimal(?val2)) AS ?longTermMedianQ)
      WHERE {
        ?obs2 a sosa:Observation ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:hasResult ?res2 .
        ?res2 qudt:numericValue ?val2 .
      }
    }

    FILTER(?nationalMedianQ < ?longTermMedianQ)
  }
}
ORDER BY ?year

generated_sparql:
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX schema: <http://schema.org/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT (COUNT(DISTINCT ?month) AS ?numMonths)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?obs a sosa:Observation ;
         sosa:madeBySensor ?station ;
         sosa:observedProperty ?property ;
         sosa:hasResult ?result ;
         sosa:resultTime ?date .
    ?station schema:name "BW_CKS022" .
    ?property schema:name "NO3N_flow_normalized" .
    ?result qudt:numericValue ?value ;
            qudt:unit unit:MilligramPerLitre .
    FILTER(?value > 10.5)
    FILTER(YEAR(?date) = 1997)
    BIND(CONCAT(STR(YEAR(?date)), "-", STR(MONTH(?date))) AS ?month)
  }
}

actual_sparql:
PREFIX hyobs:  <https://w3id.org/hmontology/>
PREFIX sosa:   <http://www.w3.org/ns/sosa/>
PREFIX schema: <http://schema.org/>
PREFIX qudt:   <http://qudt.org/schema/qudt/>
PREFIX xsd:    <http://www.w3.org/2001/XMLSchema#>
PREFIX chebi:  <http://purl.obolibrary.org/obo/CHEBI_>

SELECT (COUNT(DISTINCT ?month) AS ?monthsAbove10point5)
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?sensor a sosa:Sensor ;
            schema:name ?stationName. 
    FILTER(lcase(str(?stationName)) = "bw_cks022")

    ?obs a sosa:Observation ;
        sosa:madeBySensor ?sensor ;
        sosa:observedProperty hyobs:SoluteConcentrationFlowNormalizedMean ;
        hyobs:hasAnalyte chebi:17632 ;
        sosa:resultTime ?t ;
        sosa:hasResult ?res .

    ?res qudt:numericValue ?val .

    FILTER(YEAR(?t) = 1997)
    FILTER(xsd:decimal(?val) > 10.5)

    BIND(CONCAT(STR(YEAR(?t)), "-", STR(MONTH(?t))) AS ?month)
  }
}
